import {multiInputTask,type ExtendedPracticeField,type ExtendedPracticeTask} from './extendedPracticeTypes';

const f=(id:string,label:string,answer:string|number):ExtendedPracticeField=>({id,label,answers:[String(answer)]});

function one(lesson:number,index:number):ExtendedPracticeTask{
  const id=`l${lesson}-topup-${index+1}`;
  if(lesson<=2){const a=800+lesson*31+index*47,b=a+14+index;return multiInputTask(id,`Дополнительное закрепление: натуральный ряд от ${a} до ${b}.`,[f('previous',`Число перед ${a}`,a-1),f('next',`Число после ${a}`,a+1),f('between','Чисел строго между границами',b-a-1),f('inclusive','Чисел от первой до второй границы включительно',b-a+1)],'Различай соседние числа и включённые границы.',`Ответы: ${a-1}, ${a+1}, ${b-a-1}, ${b-a+1}.`)}
  if(lesson<=5){const value=(4+index)*1_000_000+(210+lesson*9+index*17)*1_000+43+index;return multiInputTask(id,`Дополнительное закрепление: разрядная карта числа ${value.toLocaleString('ru-RU')}.`,[f('classes','Количество классов',3),f('millions','Полных миллионов',Math.floor(value/1_000_000)),f('thousands','Полных тысяч',Math.floor(value/1_000)),f('next','Следующее натуральное число',value+1)],'Разбей число на классы и определи полные разрядные единицы.',`Классов 3; полных тысяч ${Math.floor(value/1000)}.`)}
  if(lesson<=9){const ac=24+lesson+index*5,cb=16+index*7,ab=ac+cb;return multiInputTask(id,'Дополнительное закрепление: части отрезка и длина.',[f('whole','AB, см',ab),f('mm','AB, мм',ab*10),f('left','AC, если AB и CB известны',ac),f('right','CB, если AB и AC известны',cb)],'Используй AB = AC + CB и 1 см = 10 мм.',`AB = ${ab} см = ${ab*10} мм.`)}
  if(lesson<=12){const right=index===0;return multiInputTask(id,`Дополнительное закрепление: точки A — B — C — D слева направо, луч ${right?'BC':'CB'}.`,[f('A','A принадлежит лучу?',right?'нет':'да'),f('B','B принадлежит лучу?','да'),f('C','C принадлежит лучу?','да'),f('D','D принадлежит лучу?',right?'да':'нет')],'Первая буква задаёт начало луча, вторая — направление.','Проверь начало луча и направление по порядку точек.')}
  if(lesson<=15){const step=4+index,a=step*3,b=step*7,c=step*10;return multiInputTask(id,`Дополнительное закрепление: цена деления ${step}.`,[f('A','Координата A через 3 деления',a),f('B','Координата B через 7 делений',b),f('C','Координата C через 10 делений',c),f('distance','C − A',c-a)],'Координата = число делений × цена деления.',`A=${a}, B=${b}, C=${c}.`)}
  if(lesson<=18){const low=240000+lesson*701+index*113,delta=41+index*8,high=low+delta;return multiInputTask(id,`Дополнительное закрепление: сравни ${low} и ${high}.`,[f('sign','Знак между числами','<'),f('small','Меньшее число',low),f('large','Большее число',high),f('between','Чисел строго между ними',delta-1)],'Сравни разряды, затем вычисли строгий промежуток.',`${low} < ${high}; между ними ${delta-1} чисел.`)}
  if(lesson===19){const n=1200+index*37,ac=22+index*4,cb=17+index*3,step=5+index;return multiInputTask(id,'Дополнительное итоговое закрепление первой главы.',[f('next',`Следующее число после ${n}`,n+1),f('segment',`AC=${ac}, CB=${cb}. AB`,ac+cb),f('coordinate',`Цена деления ${step}, 6 делений. Координата`,step*6),f('compare',`Знак: ${n} □ ${n+9}`,'<')],'Решай четыре пункта независимо.','Проверь натуральный ряд, части отрезка, координату и сравнение.')}
  const a=18000+lesson*101+index*503,b=3200+index*277,c=700+index*61,sum=a+b;return multiInputTask(id,'Дополнительное закрепление сложения натуральных чисел.',[f('two','Сумма первых двух',sum),f('three','Сумма трёх',sum+c),f('missing','Пропущенное второе слагаемое',b),f('zero','Первое число плюс ноль',a)],'Складывай одинаковые разряды и проверяй обратным действием.',`Ответы: ${sum}, ${sum+c}, ${b}, ${a}.`)
}

export function buildPracticeTopUp(lesson:number):ExtendedPracticeTask[]{return [one(lesson,0),one(lesson,1)]}
